  // If two routes resolve to the same (method, path), the earlier
  // entry in the array wins and publish returns an advisory for the later
  // entry. Keep \`op\` unique per route.

  // module
  export const manifest = {
    $schema: '${fc}',
    id: 'counter',
    meta: {
      name: 'Counter',
      icon: { emoji: '➕', bg: '#e8611c' },
    },
    capabilities: {
      imports: ['${ec}'],
    },
  };

  export const routes = [
    {
      op: 'increment',
      method: 'POST',
      path: '/api/increment',
      title: 'Increment counter',
      description: 'Increment the counter and return the new value.',
      inputSchema: { type: 'object', properties: {}, additionalProperties: false },
      outputSchema: {
        type: 'object',
        required: ['count'],
        properties: { count: { type: 'integer' } },
        additionalProperties: false,
      },
      annotations: {
        readOnlyHint: false,
        destructiveHint: false,
        idempotentHint: false,
        openWorldHint: false,
      },
      public: true,
      examples: [{ input: {}, output: { count: 1 } }],
      handler: async (_input, { env }) => {
        const count = ((await env.storage.get('count')) ?? 0) + 1;
        // env.storage stores JSON-compatible values directly. Do not
        // JSON.stringify before put() or JSON.parse after get().
        await env.storage.put('count', count);
        return { count };
      },
    },
  ];

  // No default export is required. Charming supplies the unmatched-path
  // 404 fallback when default.fetch is absent.

  // ui
  const root = document.getElementById('app');
  const api = window.charming.api('counter');
  root.innerHTML = '<button id="b">+1</button><span id="c">0</span> <input id="note" placeholder="type here…" />';
  const display = document.getElementById('c');
  document.getElementById('b').onclick = async () => {
    try {
      const { count } = await api.increment({});
      display.textContent = count;
    } catch (err) {
      // Unhandled CharmingOperationError surfaces an in-app toast automatically;
      // catching it here lets the agent UI render its own state instead.
      console.warn('increment failed', err);
    }
  };
  // Live updates when the agent calls this app's operations from another
  // session: window.charming.onStateChange invokes the callback with the
  // operation's value (the same shape api(id).<op>() resolves to — the
  // unwrapped 'value' from { ok, value }). Use surgical updates (textContent,
  // setAttribute, etc.) — NOT root.innerHTML = '…' — so the user's
  // unrelated input/focus/selection survives the update.
  window.charming.onStateChange((e) => {
    if (e.source === 'reconnect-resync') {
      // Connection was idle long enough that the server can't tell us what
      // we missed. Refetch state here if your app has a read route; or
      // no-op and rely on the next agent action to push fresh state.
      return;
    }
    if (e.result && typeof e.result === 'object' && 'count' in e.result) {
      display.textContent = String(e.result.count);
    }
  });
